namespace TheBarcode.Api;
public abstract class Entity { public Guid Id { get; set; } = Guid.NewGuid(); public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset UpdatedAt { get; set; } = DateTimeOffset.UtcNow; }
public sealed class StaffUser : Entity { public required string Name { get; set; } public required string PinHash { get; set; } public required string Role { get; set; } public string Permissions { get; set; } = ""; public bool Active { get; set; } = true; public bool IsDemo { get; set; } }
public sealed class Product : Entity { public required string Name { get; set; } public required string Category { get; set; } public string? Brand { get; set; } public string? Barcode { get; set; } public string Unit { get; set; } = "item"; public decimal PackageQuantity { get; set; } = 1; public string PackageUnit { get; set; } = "item"; public string TrackingMode { get; set; } = "Discrete"; public string? Supplier { get; set; } public decimal TaxRate { get; set; } public decimal CostPrice { get; set; } public decimal SellingPrice { get; set; } public decimal Stock { get; set; } public decimal MinStock { get; set; } public bool Sellable { get; set; } = true; public bool Active { get; set; } = true; public bool IsDemo { get; set; } }
public sealed class Customer : Entity { public required string Name { get; set; } public string? Phone { get; set; } public decimal CreditLimit { get; set; } public string? Notes { get; set; } public bool Active { get; set; } = true; public bool IsDemo { get; set; } }
public sealed class Sale : Entity { public required string DeviceTransactionId { get; set; } public long ReceiptNumber { get; set; } public int DailyOrderNumber { get; set; } public int? WalkInNumber { get; set; } public Guid? CustomerId { get; set; } public Guid StaffId { get; set; } public string Status { get; set; } = "Paid"; public decimal Discount { get; set; } public decimal Total { get; set; } public DateTimeOffset OccurredAt { get; set; } public DateTimeOffset? DueAt { get; set; } public DateTimeOffset? PostedAt { get; set; } public int Revision { get; set; } = 1; public string? Notes { get; set; } public bool IsDemo { get; set; } public List<SaleItem> Items { get; set; } = []; public List<Payment> Payments { get; set; } = []; public List<BillRevision> Revisions { get; set; } = []; }
