public sealed class Expense : Entity { public DateOnly Date { get; set; } public required string Category { get; set; } public required string Description { get; set; } public decimal Amount { get; set; } public decimal PaidAmount { get; set; } public required string Method { get; set; } public string? Payee { get; set; } public string? Reference { get; set; } public DateOnly? DueDate { get; set; } public decimal TaxAmount { get; set; } public string? Notes { get; set; } public bool Recurring { get; set; } public string Status { get; set; } = "Approved"; public Guid? BranchId { get; set; } public bool Active { get; set; } = true; public bool IsDemo { get; set; } public List<ExpensePayment> Payments { get; set; } = []; }
