public sealed class ReceiptConfiguration : Entity { public int PaperWidthMm { get; set; } = 80; public bool ShowBusinessDetails { get; set; } = true; public bool ShowCustomer { get; set; } = true; public bool ShowCashier { get; set; } = true; public bool ShowTax { get; set; } public bool ShowCustomerBalance { get; set; } = true; public bool ShowPoweredBy { get; set; } = true; public bool AutoPrintPaidSale { get; set; } public string CreditSalePrintMode { get; set; } = "Optional"; public string PaymentReceiptPrintMode { get; set; } = "Optional"; public int Copies { get; set; } = 1; public string Footer { get; set; } = "Thank you for your business."; public string ReceiptPrefix { get; set; } = "RCP"; public string InvoicePrefix { get; set; } = "INV"; public string PaymentPrefix { get; set; } = "PAY"; }
public sealed class InsightsConfiguration : Entity { public bool Enabled { get; set; } public string Endpoint { get; set; } = "https://api.openai.com/v1/chat/completions"; public string Model { get; set; } = "gpt-5-mini"; public string? EncryptedApiKey { get; set; } public bool AllowUserNames { get; set; } }
